  body { margin: 0; background: var(--bg-base); color: var(--text-primary); font-family: Inter, 'JetBrains Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
  .jb-demo { min-height: 100vh; padding: clamp(24px, 5vw, 64px); background: radial-gradient(circle at 7% 4%, rgba(255,49,140,.13), transparent 24%), radial-gradient(circle at 94% 16%, rgba(0,149,255,.12), transparent 28%), var(--bg-base); }
